+/// frame. `None` when the start stands at or over both tops within
+/// `z_tol`, or when the start is not finite.
+#[must_use]
+pub fn first_traverse_low_swept(
+    start: Point3,
+    tool_axis: [f64; 3],
+    clearance: f64,
+    ax: &RotaryAxis,
+    rides: &[Point3],
+    steel: SweptSteel<'_>,
